"""Render a concise report from saved artifacts, with no invented claims."""
import argparse,json,sqlite3
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--run',type=Path,required=True);p.add_argument('--pilot',type=Path,required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args()
db=sqlite3.connect(a.run/'state.sqlite');analysis=json.loads(db.execute("select payload from artifacts where key='analysis'").fetchone()[0]);db.close()
v=json.loads((a.run/'verification.json').read_text());memo=json.loads((a.run/'memo.json').read_text());experiment=json.loads((a.pilot/'experiment.json').read_text());ranking=analysis['ranking'];c=analysis['coverage'];d=sum(bool(x['disagreements']) for x in v['comparisons'])
lines=['# Spotify review analysis','',f"This run classified {c['completed']:,} of {c['source']:,} loaded reviews. It retained {c['quarantined']:,} quarantined records. The complete source contains 660,622 reviews from May 2022 through November 2023.",'',memo['recommendation'],'',memo['alternatives'],'','## Results','', '| Rank | Issue | Complaints/cancellations | Mean severity | Priority score |','|---:|---|---:|---:|---:|']
for r in ranking:lines.append(f"| {r['rank']} | {r['issue_id']} | {r['complaint_count']:,} | {r['mean_severity']} | {r['priority_score']:,} |")
lines += ['', 'Each priority score is the sum of severity across complaint and cancellation records. This is equivalent to count multiplied by the unrounded mean severity. Praise and feature requests do not enter this ranking. Ties are resolved by issue ID. All issue-level numbers are exported in `grading/claims.csv`.', '', '## Evidence']
for item in memo['citations']:
 evidence=next(r for r in analysis['evidence'][item['issue_id']] if r['review_id']==item['review_id']);quote=evidence['quote'].replace('\n',' ')
 lines += ['',f"**{item['issue_id']}** — claim `{item['claim_id']}`, review `{item['review_id']}`",'', '> '+quote]
lines += ['', '## Method and checks','', 'The pipeline reads only review text for classification. Ratings and dates remain source metadata. A pinned local NLI model evaluates short label hypotheses. A conservative English evidence guard rejects specific topics with no matching feature terminology. Separate local generative roles verify original text, describe groups, and choose a recommendation from saved aggregates. Every request and model result is saved.','',f"The independent verifier differed on at least one of topic, intent or severity for {d} of {v['sample_size']} sampled reviews. This is model disagreement, not a measured error rate. The 50 reference labels remain provisional; no human-reviewed accuracy claim is made.",'',f"The recorded 100-review pilot took {experiment['cold_wall_seconds']:.2f} seconds including interruption and resume. Its warm replay took {experiment['warm_wall_seconds']:.2f} seconds. API charges were $0. Electricity and hardware costs were not measured.",'','Exact duplicate texts reuse one saved result under the same configuration while preserving separate original IDs and direct provenance. Empty text and failed processing remain visible in the export. Saved progress is committed after each bounded request.','', '## Limits and next action','',memo['limitations'],'','Broad topics hide distinct root causes. English lexical guards and the English model can miss other languages, unusual wording, and indirect references. Sentiment scores are not calibrated probabilities. Cancellation statements are not confirmed churn, and review frequency does not measure revenue impact.','', 'Before committing the next quarter of engineering effort, inspect the leading issue’s examples and validate the suspected failure with product telemetry. A useful next experiment is to define the exact affected workflow, measure its failure rate, ship a targeted fix, and compare that failure rate and retention against a holdout. The current data does not establish the effect of that fix.','']
a.out.parent.mkdir(parents=True,exist_ok=True);a.out.write_text('\n'.join(lines));print(a.out)
